<?php

declare(strict_types=1);

namespace App\Api\Scripts;

use App\Contracts\Domains\ApiSender;
use App\Data\Profiles\ProfileDraftData;
use App\Data\Profiles\ProfileLanguageData;
use App\Data\Profiles\ProfileRunData;
use App\Support\CallKey;

/**
 * The API of Scripts, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class ScriptApi
{
    public function __construct(private ApiSender $sender) {}

    /**
     * @param  array<string, mixed>  $commands
     */
    public function checkProfileScript(
        string $profile,
        string $source,
        array $commands = [],
    ): ProfileDraftData {
        return $this->sender->send(CheckProfileScriptPayload::from([
            'profile' => $profile,
            'source' => $source,
            'commands' => $commands,
        ]));
    }

    public function readProfileLanguage(
    ): ProfileLanguageData {
        return $this->sender->send(ReadProfileLanguagePayload::from([]));
    }

    /**
     * @param  array<string, mixed>  $commands
     */
    public function saveProfileDraft(
        CallKey $requestKey,
        string $profile,
        int $expectedRevision,
        string $source,
        array $commands = [],
    ): ProfileDraftData {
        return $this->sender->send(SaveProfileDraftPayload::from([
            'requestKey' => $requestKey,
            'profile' => $profile,
            'expectedRevision' => $expectedRevision,
            'source' => $source,
            'commands' => $commands,
        ]));
    }

    public function showProfileDraft(
        string $profile,
    ): ProfileDraftData {
        return $this->sender->send(ShowProfileDraftPayload::from(['profile' => $profile]));
    }

    public function showProfileRun(
        string $id,
    ): ProfileRunData {
        return $this->sender->send(ShowProfileRunPayload::from(['id' => $id]));
    }
}
